"""Read-only Blender mesh checks using weights generated by the JS mapping.
Run on ONFIT_TShirt_BodyMorph_v2.blend with -- SAMPLES.json.
"""
import bpy
import json
import sys
import numpy as np
from pathlib import Path
from mathutils import Vector
from mathutils.bvhtree import BVHTree

samples=json.loads(Path(sys.argv[sys.argv.index('--')+1]).read_text(encoding='utf8'))
objects=[o for o in bpy.context.scene.objects if o.type=='MESH']
body=next(o for o in objects if 'abdomen_front' in o.data.shape_keys.key_blocks)
shirt=next(o for o in objects if 'garment_abdomen_front' in o.data.shape_keys.key_blocks)
# glTF does not encode Blender UI slider bounds. Enable the signed pelvis
# range for this read-only check; Three.js already supports negative weights.
body.data.shape_keys.key_blocks['pelvis_width'].slider_min=-1
shirt.data.shape_keys.key_blocks['garment_pelvis_width'].slider_min=-1
def evaluated(obj):
    evaluated=obj.evaluated_get(bpy.context.evaluated_depsgraph_get())
    mesh=evaluated.to_mesh(); mesh.calc_loop_triangles()
    points=np.array([v.co[:] for v in mesh.vertices])
    tri=np.array([t.vertices[:] for t in mesh.loop_triangles])
    evaluated.to_mesh_clear()
    return points,tri
base,tri=evaluated(shirt)
def normals(points):
    return np.cross(points[tri[:,1]]-points[tri[:,0]],points[tri[:,2]]-points[tri[:,0]])
n0=normals(base)
welded=[tuple(np.round(v,5)) for v in base]
sets=[{welded[i] for i in t} for t in tri]
results=[]
for sample in samples:
    for obj,prefix in [(body,''),(shirt,'garment_')]:
        for key in ['abdomen_front','pelvis_width']:
            obj.data.shape_keys.key_blocks[prefix+key].value=sample[key]
    bpy.context.view_layer.update()
    b,bt=evaluated(body); c,ct=evaluated(shirt)
    skin=BVHTree.FromPolygons([Vector(p) for p in b],bt.tolist(),all_triangles=True)
    cloth=BVHTree.FromPolygons([Vector(p) for p in c],ct.tolist(),all_triangles=True)
    gaps=[]
    for p in c:
        q,n,_,_=skin.find_nearest(Vector(p)); gaps.append((Vector(p)-q).dot(n))
    valid=np.linalg.norm(n0,axis=1)>1e-12
    flips=int(np.sum(np.sum(normals(c)[valid]*n0[valid],axis=1)<=0))
    overlap=len(skin.overlap(cloth))
    self_overlap=sum(i<j and not sets[i]&sets[j] for i,j in cloth.overlap(cloth))
    assert overlap==0 and self_overlap==0 and flips==0, (sample, overlap, self_overlap, flips, min(gaps))
    assert min(gaps)>0
    results.append({**sample,'min_gap_m':min(gaps),'body_overlap':overlap,'self_overlap':self_overlap,'flipped':flips})
print('ONFIT_MAPPING_CHECK',json.dumps(results))
